export function directorLabels(lang){return Object.fromEntries(DIRECTOR_KEYS.map((key,i)=>[key,(DIRECTOR_TEXT[lang]||DIRECTOR_TEXT.EN)[i]]));}
export function validateDirectorLabels(){return ['EN','HU','DE','FR','ES','IT','PT','PL'].every(lang=>DIRECTOR_TEXT[lang]?.length===DIRECTOR_KEYS.length&&DIRECTOR_TEXT[lang].every(v=>typeof v==='string'&&v.trim()));}
